def require(condition, message):
    if not condition:
        raise ValueError(message)


def sha(path):
    with Path(path).open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def write(path, value):
    with Path(path).open('x') as stream:
        json.dump(value, stream, indent=2, sort_keys=True)
        stream.write('\n')
        stream.flush()
        os.fsync(stream.fileno())


def fingerprint(path, source_only=False):
    path = Path(path).resolve(strict=True)
    item = {'path': str(path), 'kind': 'tree' if path.is_dir() else 'file', 'sourceOnly': source_only}
    if path.is_file():
        return item | {'bytes': path.stat().st_size, 'sha256': sha(path)}
    suffixes = {'.java', '.py', '.xml', '.properties'}
    files = sorted(p for p in path.rglob('*') if p.is_file()
                   and (not source_only or p.suffix in suffixes))
    require(files, 'Empty input tree: ' + str(path))
    item['files'] = [{'name': p.relative_to(path).as_posix(), 'bytes': p.stat().st_size,
                      'sha256': sha(p)} for p in files]
    return item


def environment_check():
    for name in ('JAVA_TOOL_OPTIONS', 'JDK_JAVA_OPTIONS', '_JAVA_OPTIONS', 'LD_PRELOAD'):
        require(not os.environ.get(name), 'Unprescribed runtime environment: ' + name)


def load_protocol(cohort, check_inputs=True):
    path = cohort / 'protocol.json'
    expected = (cohort / 'protocol.sha256').read_text().strip()
    require(sha(path) == expected, 'Frozen protocol changed')
    protocol = read(path)
    require(protocol['cohort'] == str(cohort) and protocol['format'] == 1, 'Wrong cohort or protocol format')
    require(protocol['arms'] == list(ARMS) and len(protocol['schedule']) == 36, 'Wrong fixed design')
    require(protocol['fixtures'] == FIXTURES and protocol['jvmArguments'] == JVM,
            'Fixed fixture or JVM design changed')
    require(protocol['runner'] == str(Path(__file__).resolve()), 'Wrong runner')
    if check_inputs:
        for item in protocol['inputs']:
            require(fingerprint(item['path'], item['sourceOnly']) == item, 'Frozen input changed: ' + item['path'])
    environment_check()
    return protocol


def freeze(args):
    environment_check()
    cohort = args.cohort.resolve()
    require(not cohort.exists(), 'Use a new cohort directory; never overwrite an attempt')
    qualification = args.qualification.resolve(strict=True)
    require(read(qualification).get('qualifiedForTiming') is True, 'Runtime has not qualified for timing')
    cp_file, overlay = args.classpath.resolve(strict=True), args.overlay.resolve(strict=True)
    require(overlay.is_dir(), 'Overlay must be a directory')
    package = overlay / 'org/eclipse/rdf4j/sail/lmdb/evaluation'
    require((package / 'NativeDirectValueMemo.class').is_file()
            and (package / 'NativeDirectValueMemo$WeakValueEntry.class').is_file(),
            'Expected the qualified weak-capable memo prefix')
    classpath = [str(overlay)] + [str(Path(p).resolve(strict=True))
                                 for p in cp_file.read_text().strip().split(os.pathsep)
                                 if Path(p).resolve() != overlay]
    require(len(classpath) == len(set(classpath)), 'Duplicate classpath entry')
    java = args.java.resolve(strict=True)
    jdk = java.parent.parent
    release = dict(line.split('=', 1) for line in (jdk / 'release').read_text().splitlines() if '=' in line)
    java_version = release['JAVA_RUNTIME_VERSION'].strip('"')
    require(java_version == '25.0.5+8-LTS', 'Use the selected Temurin 25.0.5+8 runtime')
    sources = [Path(__file__).resolve(), HERE / 'analyze_comparison.py', cp_file, qualification,
               *[p.resolve(strict=True) for p in args.source]]
    require(all(not p.is_dir() or not cohort.is_relative_to(p) for p in sources),
            'A source input cannot contain the mutable cohort directory')
    paths = [(p, False) for p in classpath] + [(p, True) for p in sources]
    paths += [(java, False), (jdk / 'release', False), (jdk / 'lib/modules', False),
              (jdk / 'conf', False)]
    paths += [(p, False) for p in sorted((jdk / 'lib').rglob('*.so'))]
    inputs = [fingerprint(p, source_only) for p, source_only in paths]
    identity = hashlib.sha256(json.dumps(inputs, sort_keys=True).encode()).hexdigest()
    source_identity = 'retention-fresh-runtime-sha256-' + identity
    schedule = []
    for round_index, order in enumerate(itertools.permutations(ARMS)):
        fixture_order = list(FIXTURES) if round_index % 2 == 0 else list(reversed(FIXTURES))
        for fixture_position, fixture in enumerate(fixture_order):
            for position, arm in enumerate(order):
                folder = cohort / f'round-{round_index:02d}-{fixture_position:02d}-{fixture}-{position:02d}-{arm}'
                properties = {TRANSPORT: 'off', ENABLED: str(arm != 'ordinary').lower(),
                              RETENTION: 'weak' if arm == 'weak' else 'strong'}
                command = [str(java), *JVM, '-Xlog:gc:file=' + str(folder / 'gc.log') + ':uptime,level,tags',
                           *['-D' + key + '=' + value for key, value in properties.items()],
                           '-cp', os.pathsep.join(classpath), LAUNCHER, fixture, '--arm=' + arm,
                           '--source=' + source_identity, '--warmup=8', '--iterations=5',
                           *FIXTURES[fixture]['arguments'], '--consumption=full',
                           '--output=' + str(folder / 'samples.jsonl'), '--store=' + str(folder / 'store')]
                schedule.append({'ordinal': len(schedule), 'round': round_index, 'position': position,
                                 'fixturePosition': fixture_position, 'fixture': fixture, 'arm': arm,
                                 'directory': str(folder), 'properties': properties, 'command': command})
    protocol = {'format': 1, 'cohort': str(cohort), 'cwd': str(ROOT), 'frozenEpochNs': time.time_ns(),
                'runner': str(Path(__file__).resolve()), 'analyzer': str(HERE / 'analyze_comparison.py'),
                'arms': list(ARMS), 'fixtures': FIXTURES, 'configuration': CONFIG, 'jvmArguments': JVM,
                'javaVersion': java_version, 'sourceIdentity': source_identity, 'classpath': classpath,
                'qualificationFile': str(qualification), 'inputs': inputs, 'schedule': schedule,
                'warmups': 8, 'measurements': 5, 'timeoutSeconds': 300,
                'expectedCounts': {'jvms': 36, 'queries': 468, 'warmups': 288, 'measurements': 180},
                'statisticsScope': 'native-direct-memo-retention-v1', 'statisticsFormat': 2,
                'metadataReservation': {'arrayBase': 80, 'arrayPerSlot': 36,
                                        'weakMetadataPerSlot': 112, 'weakMetadataOverlap': 160},
                'estimator': 'Six same-round ratios of per-JVM medians of all five measured queries, per fixture.',
                'decision': 'Descriptive engineering comparison; no significance claim or production-promotion threshold.',
                'admission': 'Unchanged cumulative direct-map adaptation; collection and adaptive outcomes are reported.',
                'memoryScope': 'Strong arrays only; weak arrays plus reserved weak metadata. Neither is total query heap.',
                'gcScope': 'Whole-JVM unified GC log, including setup, warmup and measurement; natural GC only.',
                'execution': 'Exactly one JVM per next invocation; exclusive Java slot; no concurrent build or diagnostic.',
                'integrity': 'Full input hashes before and after each JVM, outside timed work. All raw outputs are sealed.',
                'failure': 'A partial, failed, changed or unclaimed slot permanently blocks this cohort; no replacement.',
                'pooling': 'Fresh controls only. Never pool historical, diagnostic, warmup or incomplete-cohort timings.'}
    cohort.mkdir(parents=True, exist_ok=False)
    (cohort / 'claims').mkdir()
    write(cohort / 'protocol.json', protocol)
    with (cohort / 'protocol.sha256').open('x') as stream:
        stream.write(sha(cohort / 'protocol.json') + '\n')
        stream.flush()
        os.fsync(stream.fileno())
    print(json.dumps({'frozen': str(cohort), 'protocolSha256': sha(cohort / 'protocol.json'),
                      'scheduledJvms': 36, 'launchedJvms': 0}))


def completed_prefix(cohort, protocol):
    require(not (cohort / 'failure.json').exists(), 'This cohort has a permanent failure receipt')
    claims = sorted((cohort / 'claims').iterdir())
    require(len(claims) <= 36 and [p.name for p in claims] == [f'{i:02d}.json' for i in range(len(claims))],
            'Claims contain an extra slot or chronology gap')
    require({p.name for p in cohort.glob('round-*')} ==
            {Path(s['directory']).name for s in protocol['schedule'][:len(claims)]},
            'Unclaimed or missing run directory')
    previous_end = 0
    runs = []
    for slot in protocol['schedule'][:len(claims)]:
        run = analysis.inspect_slot(protocol, slot, require_completion=True)
        require(run['process']['startedEpochNs'] >= previous_end, 'JVM intervals overlap')
        previous_end = run['process']['finishedEpochNs']
        runs.append(run)
    analysis.match_runs(runs)
    return runs


def execute_one(args, cohort, protocol):
    require(args.slot_released, 'The coordinator must release the exclusive Java slot')
    prior = completed_prefix(cohort, protocol)
    require(len(prior) < 36, 'All 36 slots have already completed; use audit')
    slot = protocol['schedule'][len(prior)]
    folder = Path(slot['directory'])
    claim = {'ordinal': slot['ordinal'], 'protocolSha256': sha(cohort / 'protocol.json'),
             'claimedEpochNs': time.time_ns(), 'command': slot['command'], 'cwd': str(ROOT)}
    write(cohort / 'claims' / f"{slot['ordinal']:02d}.json", claim)
    folder.mkdir()
    print(f"Launching {slot['ordinal'] + 1}/36: round {slot['round'] + 1}, {slot['fixture']}, {slot['arm']}", flush=True)
    process, failure = None, None
    started = time.time_ns()
    try:
        with (folder / 'console.log').open('xb') as console:
            process = subprocess.Popen(slot['command'], cwd=ROOT, stdout=console, stderr=subprocess.STDOUT,
                                       start_new_session=True)
            write(folder / 'launch.json', {'ordinal': slot['ordinal'], 'argv': slot['command'],
                                           'cwd': str(ROOT), 'pid': process.pid, 'startedEpochNs': started})
            deadline = time.monotonic() + protocol['timeoutSeconds']
            while True:
                remaining = deadline - time.monotonic()
                require(remaining > 0, 'Prespecified 300-second JVM deadline exceeded')
                try:
                    code = process.wait(timeout=min(30, remaining))
                    require(code == 0, 'JVM exited with status ' + str(code))
                    break
                except subprocess.TimeoutExpired:
                    print('JVM still running; output is being preserved.', flush=True)
    except BaseException as problem:
        failure = {'exception': type(problem).__name__, 'message': str(problem)}
    finally:
        if process is not None and process.poll() is None:
            os.killpg(process.pid, signal.SIGTERM)
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait(timeout=5)
        write(folder / 'process.json', {'startedEpochNs': started, 'finishedEpochNs': time.time_ns(),
                                        'exitCode': process.returncode if process else None, 'failure': failure})
    if failure is not None:
        write(cohort / 'failure.json', {'ordinal': slot['ordinal'], 'failure': failure})
        raise ValueError('JVM failed; preserved attempt cannot be retried: ' + failure['message'])
    try:
        load_protocol(cohort)  # Verify runtime/source immutability after the measured process has exited.
        run = analysis.inspect_slot(protocol, slot, require_completion=False)
        analysis.match_runs(prior + [run])
        write(folder / 'validation.json', {'qualified': True, 'queries': 13, 'measurements': 5,
                                          'medians': run['medians'], 'gcWholeJvm': run['gc']})
        raw = {name: sha(folder / name) for name in analysis.RAW_FILES}
        write(folder / 'completion.json', {'ordinal': slot['ordinal'], 'completedEpochNs': time.time_ns(),
                                           'protocolSha256': sha(cohort / 'protocol.json'),
                                           'claimSha256': sha(cohort / 'claims' / f"{slot['ordinal']:02d}.json"),
                                           'rawHashes': raw})
    except BaseException as problem:
        write(cohort / 'failure.json', {'ordinal': slot['ordinal'], 'failure': str(problem)})
        raise
    print(json.dumps({'completed': slot['ordinal'] + 1, 'remaining': 35 - slot['ordinal'],
                      'fixture': slot['fixture'], 'arm': slot['arm'], 'medianTotalNs': run['medians']['totalNs']}))


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest='action', required=True)
    create = commands.add_parser('freeze', aliases=['init'])
    create.add_argument('--cohort', type=Path, required=True)
    create.add_argument('--classpath', type=Path, default=PHASE / 'recovery/runtime-v1/direct/classpath.txt')
    create.add_argument('--overlay', type=Path, default=PHASE / 'runtime-v1/classes')
    create.add_argument('--java', type=Path, default=JAVA)
    create.add_argument('--source', type=Path, action='append', required=True)
    create.add_argument('--qualification', type=Path, required=True)
    for name in ('next', 'status', 'audit'):
        sub = commands.add_parser(name)
        sub.add_argument('--cohort', type=Path, required=True)
        if name == 'next':
            sub.add_argument('--slot-released', action='store_true')
    args = parser.parse_args()
    if args.action in ('freeze', 'init'):
        freeze(args)
        return
    cohort = args.cohort.resolve(strict=True)
    with (cohort / 'runner.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        protocol = load_protocol(cohort)
        if args.action == 'next':
            execute_one(args, cohort, protocol)
        else:
            runs = completed_prefix(cohort, protocol)
            if args.action == 'audit':
                require(len(runs) == 36, 'Incomplete cohort: no accepted comparison estimates')
                result = analysis.summarize(protocol, runs)
                write(cohort / 'audit.json', result)
            print(json.dumps({'completedJvms': len(runs), 'remainingJvms': 36 - len(runs),
                              'complete': len(runs) == 36, 'action': args.action}))


if __name__ == '__main__':
    main()
